// static
bool StructTraits<::side_panel::mojom::Note::DataView, ::side_panel::mojom::NotePtr>::Read(
    ::side_panel::mojom::Note::DataView input,
    ::side_panel::mojom::NotePtr* output) {
  bool success = true;
  ::side_panel::mojom::NotePtr result(::side_panel::mojom::Note::New());
  
      if (success && !input.ReadGuid(&result->guid))
        success = false;
      if (success && !input.ReadUrl(&result->url))
        success = false;
      if (success && !input.ReadLastModificationTime(&result->last_modification_time))
        success = false;
      if (success && !input.ReadLastModificationTimeText(&result->last_modification_time_text))
        success = false;
      if (success && !input.ReadText(&result->text))
        success = false;
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::side_panel::mojom::NoteOverview::DataView, ::side_panel::mojom::NoteOverviewPtr>::Read(
    ::side_panel::mojom::NoteOverview::DataView input,
    ::side_panel::mojom::NoteOverviewPtr* output) {
  bool success = true;
  ::side_panel::mojom::NoteOverviewPtr result(::side_panel::mojom::NoteOverview::New());
  
      if (success && !input.ReadUrl(&result->url))
        success = false;
      if (success && !input.ReadTitle(&result->title))
        success = false;
      if (success && !input.ReadText(&result->text))
        success = false;
      if (success)
        result->num_notes = input.num_notes();
      if (success)
        result->is_current_tab = input.is_current_tab();
      if (success && !input.ReadLastModificationTime(&result->last_modification_time))
        success = false;
  *output = std::move(result);
  return success;
}

